library(tidyverse)

# Function to calculate percent identity between two sequences
calculate_identity <- function(seq1, seq2) {
  if (is.null(seq1) || is.null(seq2) || 
      nchar(seq1) == 0 || nchar(seq2) == 0) {
    return(NA)
  }
  
  # Create AAString objects
  aa1 <- AAString(seq1)
  aa2 <- AAString(seq2)
  
  # Perform pairwise alignment
  alignment <- pairwiseAlignment(aa1, aa2, type = "global")
  
  # Calculate percent identity
  pid <- pid(alignment, type = "PID1")  # PID1: (identical positions / length of alignment) * 100
  
  return(pid)
}

# Function to compare all common products between two strains
compare_strains <- function(strain1, strain1_name, strain2, strain2_name) {
  common_products <- intersect(names(strain1), names(strain2))
  
  if (length(common_products) == 0) {
    cat("No common products found between", strain1_name, "and", strain2_name, "\n")
    return(NULL)
  }
  
  results <- data.frame(
    Product = character(),
    Strain1 = character(),
    Strain2 = character(),
    Percent_Identity = numeric(),
    Length1 = integer(),
    Length2 = integer(),
    Length_Diff = integer(),
    stringsAsFactors = FALSE
  )
  
  for (product in common_products) {
    seq1 <- strain1[[product]]
    seq2 <- strain2[[product]]
    
    identity <- calculate_identity(seq1, seq2)
    len1 <- nchar(seq1)
    len2 <- nchar(seq2)
    len_diff <- abs(len1 - len2)
    
    results <- rbind(results, data.frame(
      Product = product,
      Strain1 = strain1_name,
      Strain2 = strain2_name,
      Percent_Identity = identity,
      Length1 = len1,
      Length2 = len2,
      Length_Diff = len_diff
    ))
  }
  
  return(results)
}

# Function to create a percent identity matrix for all strain comparisons
create_identity_matrix <- function(all_strains) {
  strain_names <- names(all_strains)
  n_strains <- length(strain_names)
  
  # Get all unique products across all strains
  all_products <- unique(unlist(lapply(all_strains, names)))
  
  # Initialize results list
  all_results <- list()
  
  # Perform all pairwise comparisons
  for (i in 1:(n_strains - 1)) {
    for (j in (i + 1):n_strains) {
      strain1_name <- strain_names[i]
      strain2_name <- strain_names[j]
      
      comparison <- compare_strains(
        all_strains[[i]], strain1_name,
        all_strains[[j]], strain2_name
      )
      
      if (!is.null(comparison)) {
        all_results[[paste(strain1_name, "vs", strain2_name)]] <- comparison
      }
    }
  }
  
  return(all_results)
}

# Function to generate summary statistics
generate_summary <- function(results_list) {
  summary_df <- data.frame(
    Comparison = character(),
    Mean_Identity = numeric(),
    Median_Identity = numeric(),
    Min_Identity = numeric(),
    Max_Identity = numeric(),
    SD_Identity = numeric(),
    N_Comparisons = integer(),
    stringsAsFactors = FALSE
  )
  
  for (comp_name in names(results_list)) {
    comp_data <- results_list[[comp_name]]
    
    summary_df <- rbind(summary_df, data.frame(
      Comparison = comp_name,
      Mean_Identity = mean(comp_data$Percent_Identity, na.rm = TRUE),
      Median_Identity = median(comp_data$Percent_Identity, na.rm = TRUE),
      Min_Identity = min(comp_data$Percent_Identity, na.rm = TRUE),
      Max_Identity = max(comp_data$Percent_Identity, na.rm = TRUE),
      SD_Identity = sd(comp_data$Percent_Identity, na.rm = TRUE),
      N_Comparisons = nrow(comp_data)
    ))
  }
  
  return(summary_df)
}

