# Print summary
cat("\n=== SUMMARY STATISTICS ===\n")
print(summary_stats)

# Display detailed results for each comparison
cat("\n=== DETAILED RESULTS ===\n")
for (comp_name in names(pairwise_results)) {
  cat("\n", comp_name, ":\n")
  print(pairwise_results[[comp_name]] %>%
          arrange(desc(Percent_Identity)) %>%
          select(Product, Percent_Identity, Length1, Length2, Length_Diff))
}

# Save results to files
if (length(pairwise_results) > 0) {
  # Save detailed results
  for (comp_name in names(pairwise_results)) {
    filename <- paste0(gsub(" ", "_", comp_name), "_identity_results.csv")
    write.csv(pairwise_results[[comp_name]], filename, row.names = FALSE)
    cat("Saved", filename, "\n")
  }
  
  # Save summary
  write.csv(summary_stats, "pairwise_identity_summary.csv", row.names = FALSE)
  cat("Saved pairwise_identity_summary.csv\n")
}

# Identify highly conserved and divergent proteins
cat("\n=== HIGHLY CONSERVED PROTEINS (>95% identity) ===\n")
highly_conserved <- bind_rows(pairwise_results, .id = "Comparison") %>%
  filter(Percent_Identity > 95) %>%
  arrange(desc(Percent_Identity))

if (nrow(highly_conserved) > 0) {
  print(highly_conserved)
} else {
  cat("No highly conserved proteins found.\n")
}

cat("\n=== DIVERGENT PROTEINS (<80% identity) ===\n")
divergent <- bind_rows(pairwise_results, .id = "Comparison") %>%
  filter(Percent_Identity < 80) %>%
  arrange(Percent_Identity)

if (nrow(divergent) > 0) {
  print(divergent)
} else {
  cat("No highly divergent proteins found.\n")
}

